solution.js:
const expenses = [
  { label: "coffee", amount: 450, category: "food" },
  { label: "Train", amount: 1220, category: "travel" },
  { label: "Lunch", amount: 1350, category: "food" },
  { label: "Museum", amount: 99, category: "fun" },
];

function totalCents(expenses) {
  return expenses.reduce((sum, e) => sum + e.amount, 0);
}

function totalsByCategory(expenses) {
  return expenses.reduce((totals, e) => {
    totals[e.category] = (totals[e.category] ?? 0) + e.amount;
    return totals;
  }, {});
}

function biggestFirst(expenses) {
  return expenses.toSorted((a, b) => b.amount - a.amount);
}

function alphabetical(expenses) {
  return expenses.toSorted((a, b) => a.label.localeCompare(b.label));
}

console.log(totalCents(expenses), totalsByCategory(expenses));

